style.css:
@-moz-document domain("tiktok.com") {
/* Hide everything on the page */
  * {
    display: none !important;
  }

  /* Specifically show the video container */
  .tiktok-1nylt8u-DivContainer, /* The main video container */
  .tiktok-1u7g1g6-DivVideoWrapper, /* Video wrapper */
  video {
    display: block !important;
    width: 100% !important;
    height: 100% !important;
  }

  /* Optional: Center the video on the screen */
  .tiktok-1nylt8u-DivContainer {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }
}
